export function getWatchById(id: string): WatchProduct | undefined {
  return WATCH_CATALOG.find((w) => w.id === id)
}

export function getFeaturedWatches(): WatchProduct[] {
  return WATCH_CATALOG.filter((w) => w.featured)
}

